        public ReadOnlyMemorySlice<Byte>? SPIT => _SPITLocation.HasValue ? HeaderTranslation.ExtractSubrecordMemory(_recordData, _SPITLocation.Value, _package.MetaData.Constants) : default(ReadOnlyMemorySlice<byte>?);
        #endregion
        partial void CustomFactoryEnd(
            OverlayStream stream,
            int finalPos,
            int offset);

        partial void CustomCtor();
        protected SpellBinaryOverlay(
            MemoryPair memoryPair,
            BinaryOverlayFactoryPackage package)
            : base(
                memoryPair: memoryPair,
                package: package)
        {
            this.CustomCtor();
        }

        public static ISpellGetter SpellFactory(
            OverlayStream stream,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            stream = Decompression.DecompressStream(stream);
            stream = ExtractRecordMemory(
                stream: stream,
                meta: package.MetaData.Constants,
                memoryPair: out var memoryPair,
                offset: out var offset,
                finalPos: out var finalPos);
            var ret = new SpellBinaryOverlay(
                memoryPair: memoryPair,
                package: package);
            ret._package.FormVersion = ret;
            ret.CustomFactoryEnd(
                stream: stream,
                finalPos: finalPos,
                offset: offset);
            ret.FillSubrecordTypes(
                majorReference: ret,
                stream: stream,
                finalPos: finalPos,
                offset: offset,
                translationParams: translationParams,
                fill: ret.FillRecordType);
            return ret;
        }

        public static ISpellGetter SpellFactory(
            ReadOnlyMemorySlice<byte> slice,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            return SpellFactory(
                stream: new OverlayStream(slice, package),
                package: package,
                translationParams: translationParams);
        }

        public override ParseResult FillRecordType(
            OverlayStream stream,
            int finalPos,
            int offset,
            RecordType type,
            PreviousParse lastParsed,
            Dictionary<RecordType, int>? recordParseCount,
            TypedParseParams translationParams = default)
        {
            type = translationParams.ConvertToStandard(type);
            switch (type.TypeInt)
            {
                case RecordTypeInts.EDID:
                {
                    if (!lastParsed.ParsedIndex.HasValue)
                    {
                        return base.FillRecordType(
                            stream: stream,
                            finalPos: finalPos,
                            offset: offset,
                            type: type,
                            lastParsed: lastParsed,
                            recordParseCount: recordParseCount,
                            translationParams: translationParams.WithNoConverter());
                    }
                    else if (lastParsed.ParsedIndex.Value <= (int)MajorRecord_FieldIndex.EditorID)
                    {
                        _EDIDLocation = (stream.Position - offset);
                        return new ParseResult((int)Spell_FieldIndex.EDID, type);
                    }
                    else
                    {
                        switch (recordParseCount?.GetOrAdd(type) ?? 0)
                        {
                            case 0:
                            {
                                return base.FillRecordType(
                                    stream: stream,
                                    finalPos: finalPos,
                                    offset: offset,
                                    type: type,
                                    lastParsed: lastParsed,
                                    recordParseCount: recordParseCount,
                                    translationParams: translationParams.WithNoConverter());
                            }
                            case 1:
                            {
                                _EDIDLocation = (stream.Position - offset);
                                return new ParseResult((int)Spell_FieldIndex.EDID, type);
                            }
                            default:
                                throw new NotImplementedException();
                        }
                    }
                }
                case RecordTypeInts.OPDS:
                {
                    this.ObjectPlacementDefaults = BinaryOverlayList.FactoryByArray<IObjectPlacementDefaultGetter>(
                        mem: stream.RemainingMemory,
                        package: _package,
                        translationParams: translationParams,
                        getter: (s, p, recConv) => ObjectPlacementDefaultBinaryOverlay.ObjectPlacementDefaultFactory(new OverlayStream(s, p), p, recConv),
                        locs: ParseRecordLocations(
                            stream: stream,
                            trigger: ObjectPlacementDefault_Registration.TriggerSpecs,
                            triggersAlwaysAreNewRecords: true,
                            constants: _package.MetaData.Constants.SubConstants,
                            skipHeader: false));
                    return (int)Spell_FieldIndex.ObjectPlacementDefaults;
                }
                case RecordTypeInts.OBND:
                {
                    _ObjectBoundsLocation = new RangeInt32((stream.Position - offset), finalPos - offset);
                    return (int)Spell_FieldIndex.ObjectBounds;
                }
                case RecordTypeInts.PHST:
                {
                    _PHSTLocation = (stream.Position - offset);
                    return (int)Spell_FieldIndex.PHST;
                }
                case RecordTypeInts.DEFL:
                {
                    _DefaultLayerLocation = (stream.Position - offset);
                    return (int)Spell_FieldIndex.DefaultLayer;
                }
                case RecordTypeInts.FULL:
                {
                    _FULLLocation = (stream.Position - offset);
                    return (int)Spell_FieldIndex.FULL;
                }
                case RecordTypeInts.KSIZ:
                case RecordTypeInts.KWDA:
                {
                    this.Keywords = BinaryOverlayList.FactoryByCount<IFormLinkGetter<IKeywordGetter>>(
                        stream: stream,
                        package: _package,
                        itemLength: 0x4,
                        countLength: 4,
                        countType: RecordTypes.KSIZ,
                        trigger: RecordTypes.KWDA,
                        getter: (s, p) => FormLinkBinaryTranslation.Instance.OverlayFactory<IKeywordGetter>(p, s));
                    return (int)Spell_FieldIndex.Keywords;
                }
                case RecordTypeInts.MDOB:
                {
                    _MenuDisplayObjectLocation = (stream.Position - offset);
                    return (int)Spell_FieldIndex.MenuDisplayObject;
                }
                case RecordTypeInts.ETYP:
                {
                    _EquipmentTypeLocation = (stream.Position - offset);
                    return (int)Spell_FieldIndex.EquipmentType;
                }
                case RecordTypeInts.DESC:
                {
                    _DESCLocation = (stream.Position - offset);
                    return (int)Spell_FieldIndex.DESC;
                }
                case RecordTypeInts.MIID:
                {
                    _MIIDLocation = (stream.Position - offset);
                    return (int)Spell_FieldIndex.MIID;
                }
                case RecordTypeInts.EFID:
                {
                    _BaseEffectLocation = (stream.Position - offset);
                    return (int)Spell_FieldIndex.BaseEffect;
                }
                case RecordTypeInts.EFIT:
                {
                    _EFITLocation = (stream.Position - offset);
                    return (int)Spell_FieldIndex.EFIT;
                }
                case RecordTypeInts.CIS2:
                {
                    _CIS2Location = (stream.Position - offset);
                    return (int)Spell_FieldIndex.CIS2;
                }
                case RecordTypeInts.CODG:
                {
                    _CODGLocation = (stream.Position - offset);
                    return (int)Spell_FieldIndex.CODG;
                }
                case RecordTypeInts.CODV:
                {
                    _CODVLocation = (stream.Position - offset);
                    return (int)Spell_FieldIndex.CODV;
                }
                case RecordTypeInts.CTDA:
                case RecordTypeInts.CITC:
                {
                    this.Conditions = BinaryOverlayList.FactoryByCountPerItem<IConditionGetter>(
                        stream: stream,
                        package: _package,
                        countLength: 4,
                        trigger: Condition_Registration.TriggerSpecs,
                        countType: RecordTypes.CITC,
                        translationParams: translationParams,
                        getter: (s, p, recConv) => ConditionBinaryOverlay.ConditionFactory(new OverlayStream(s, p), p, recConv),
                        skipHeader: false);
                    return (int)Spell_FieldIndex.Conditions;
                }
                case RecordTypeInts.CVT0:
                {
                    _CVT0Location = (stream.Position - offset);
                    return (int)Spell_FieldIndex.CVT0;
                }
                case RecordTypeInts.DURG:
                {
                    _DURGLocation = (stream.Position - offset);
                    return (int)Spell_FieldIndex.DURG;
                }
                case RecordTypeInts.EIES:
                {
                    _EIESLocation = (stream.Position - offset);
                    return (int)Spell_FieldIndex.EIES;
                }
                case RecordTypeInts.MAGA:
                {
                    _MAGALocation = (stream.Position - offset);
                    return (int)Spell_FieldIndex.MAGA;
                }
                case RecordTypeInts.MAGF:
                {
                    _MAGFLocation = (stream.Position - offset);
                    return (int)Spell_FieldIndex.MAGF;
                }
                case RecordTypeInts.MAGG:
                {
                    _MAGGLocation = (stream.Position - offset);
                    return (int)Spell_FieldIndex.MAGG;
                }
                case RecordTypeInts.SPIT:
                {
                    _SPITLocation = (stream.Position - offset);
                    return (int)Spell_FieldIndex.SPIT;
                }
                default:
                    return base.FillRecordType(
                        stream: stream,
                        finalPos: finalPos,
                        offset: offset,
                        type: type,
                        lastParsed: lastParsed,
                        recordParseCount: recordParseCount,
                        translationParams: translationParams.WithNoConverter());
            }
        }
